import pandas as pd,numpy as np,glob
from scipy.optimize import least_squares
D=[pd.read_csv(f).values[::5] for f in sorted(glob.glob('train/*.csv'))]
dt=0.005
def sim(p,d):
  Tw,Kp,Tp,Kq,Tq=p
  th=d[:,4];V=d[:,3];Vs=d[:,5];P0,Q0=d[0,1],d[0,2]
  xs=th[0];pp=P0;q=Q0;out=[]
  for k in range(len(d)):
    w=(th[k]-xs)/Tw
    out.append((pp,q))
    xs+=dt*w; pp+=dt*(P0-Kp*w/377-pp)/Tp; q+=dt*(Q0+Kq*(Vs[k]-V[k])-q)/Tq
  return np.array(out)
def res(p):
  return np.concatenate([(sim(p,d)-d[:,1:3]).ravel() for d in D])
r=least_squares(res,[0.05,17,0.2,10,0.1],bounds=([0.006,0,0.006,0,0.006],[2,100,5,200,5]))
print(r.x, np.sqrt(np.mean(r.fun**2)))
for d in D: e=sim(r.x,d)-d[:,1:3];print(e.std(0).round(4),d[:,1:3].std(0).round(4))
np.save('p.npy',r.x)

