D=[pd.read_csv(f).values[::5] for f in sorted(glob.glob('train/*.csv'))];dt=0.005
def simq(p,d):
  Kq,Tq,Ka,Kpp=p
  V=d[:,3];Vs=d[:,5];Q0=d[0,2];P=d[:,1]-d[0,1]
  q=Q0;out=[]
  for k in range(len(d)):
    out.append(q+Ka*(Vs[k]-V[k])+Kpp*P[k])
    q+=dt*(Q0+Kq*(Vs[k]-V[k])-q)/Tq
  return np.array(out)
def resq(p): return np.concatenate([simq(p,d)-d[:,2] for d in D])
